"""Probe which PDF libraries are available in this environment."""
import importlib

for mod in ["reportlab", "fpdf", "pypdf", "PyPDF2", "pdfplumber", "weasyprint", "fitz", "pymupdf"]:
    try:
        importlib.import_module(mod)
        print(f"{mod}: AVAILABLE")
    except Exception as exc:
        print(f"{mod}: not available ({type(exc).__name__})")

"""Byte-level integrity check: renumbered report objects must equal renumbered originals."""
import re


def parse_xref(data):
    m = re.search(rb"startxref\s+(\d+)", data)
    xref_pos = int(m.group(1))
    section = data[xref_pos:].split(b"\n")
    entries = {}
    i = 1
    while i < len(section):
        line = section[i].strip()
        if not line:
            i += 1
            continue
        if line == b"trailer":
            break
        hm = re.match(rb"(\d+)\s+(\d+)", line)
        if hm:
            start, count = int(hm.group(1)), int(hm.group(2))
            i += 1
            for _ in range(count):
                if i < len(section):
                    em = re.match(rb"(\d{10})\s(\d{5})\s([nf])", section[i])
                    if em and em.group(3) == b"n":
                        entries[start] = int(em.group(1))
                    start += 1
                i += 1
        else:
            i += 1
    return entries


def extract_object(data, offset):
    header_end = data.find(b"obj", offset)
    dict_start = header_end + 3
    stream_idx = data.find(b"stream", dict_start)
    endobj_idx = data.find(b"endobj", dict_start)
    if stream_idx != -1 and stream_idx < endobj_idx:
        endstream_idx = data.find(b"endstream", stream_idx)
        endobj_idx = data.find(b"endobj", endstream_idx)
    return data[dict_start:endobj_idx].strip()


with open("report.pdf", "rb") as f:
    orig = f.read()
with open("report_with_cover.pdf", "rb") as f:
    merged = f.read()

orig_entries = parse_xref(orig)
merged_entries = parse_xref(merged)
if 0 in orig_entries:
    del orig_entries[0]

# original catalog is 5 (dropped in merge); cover occupies 1..6; shift = 6
COVER_OBJ_COUNT = 6
catalog_num = 5
ok = True
for old, off in sorted(orig_entries.items()):
    if old == catalog_num:
        continue
    new = old + COVER_OBJ_COUNT
    orig_body = extract_object(orig, off)
    merged_body = extract_object(merged, merged_entries[new])

    def renumber(body):
        def repl(m):
            o = int(m.group(1))
            return (str(o + COVER_OBJ_COUNT).encode() + b" 0 R") if o != catalog_num else m.group(0)
        return re.sub(rb"(\d+)\s+0\s+R", repl, body)

    if renumber(orig_body) != merged_body:
        print(f"  MISMATCH: report object {old} -> {new}")
        ok = False
    else:
        print(f"  ok: report object {old} -> {new} identical after renumbering")

print("report object integrity:", "PASS" if ok else "FAIL")

